# Approach 1: Recursive (inefficient for large n)
def fibonacci_recursive(n):
    """Recursive Fibonacci - clear but inefficient."""
    if n <= 1:
        return n
    return fibonacci_recursive(n-1) + fibonacci_recursive(n-2)

# Common Mistake: Recursive without memoization for repeated calculations
# This leads to exponential time complexity

# Approach 2: Iterative (efficient)
def fibonacci_iterative(n):
    """Iterative Fibonacci - efficient O(n) time, O(1) space."""
    if n <= 1:
        return n

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

# Approach 3: Memoization (caching)
def fibonacci_memoized(n, memo=None):
    """Memoized recursive Fibonacci - efficient with caching."""
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        return n

    memo[n] = fibonacci_memoized(n-1, memo) + fibonacci_memoized(n-2, memo)
    return memo[n]

