import time
import functools
from datetime import datetime, timedelta

class RateLimiter:
    """Decorator-based rate limiting for API endpoints."""

    def __init__(self, calls_per_minute=60):
        self.calls_per_minute = calls_per_minute
        self.call_timestamps = []

    def __call__(self, func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            current_time = time.time()

            # Clean up old timestamps
            self.call_timestamps = [
                ts for ts in self.call_timestamps 
                if current_time - ts < 60
            ]

            if len(self.call_timestamps) >= self.calls_per_minute:
                raise RateLimitExceeded("API rate limit exceeded")

            self.call_timestamps.append(current_time)
            return func(*args, **kwargs)
        return wrapper

class PerformanceMonitor:
    """Decorator for tracking function performance."""

    def __init__(self, func):
        self.func = func
        self.call_count = 0
        self.total_time = 0
        functools.update_wrapper(self, func)

    def __call__(self, *args, **kwargs):
        start_time = time.time()
        result = self.func(*args, **kwargs)
        end_time = time.time()

        self.call_count += 1
        self.total_time += (end_time - start_time)

        return result

    @property
    def average_time(self):
        return self.total_time / self.call_count if self.call_count > 0 else 0

# Common Mistake: Decorators that don't preserve function metadata
# def bad_decorator(func):
#     def wrapper(*args, **kwargs):
#         return func(*args, docstring, name, etc.

# Advanced: Parameterized decorator factory
def retry(max_attempts=3, delay=1, backoff=2):
    """Decorator factory for retrying failed operations."""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            current_delay = delay

            while attempts < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempts += 1
                    if attempts == max_attempts:
                        raise
                    time.sleep(current_delay)
                    current_delay *= backoff
            return None
        return wrapper
    return decorator

# Usage examples
