class DynamicModelMeta(type):
    """Metaclass for creating dynamic ORM models."""

    def __new__(cls, name, bases, attrs):
        # Automatically add table name based on class name
        if 'table_name' not in attrs:
            attrs['table_name'] = f"{name.lower()}s"

        # Add created_at and updated_at fields if not specified
        if 'fields' in attrs:
            if 'created_at' not in attrs['fields']:
                attrs['fields']['created_at'] = {'type': 'datetime'}
            if 'updated_at' not in attrs['fields']:
                attrs['fields']['updated_at'] = {'type': 'datetime'}

        return super().__new__(cls, name, bases, attrs)

    def __init__(cls, name, bases, attrs):
        super().__init__(name, bases, attrs)
        # Register model in registry
        if not hasattr(cls, '_registry'):
            cls._registry = {}
        cls._registry[name] = cls

class Model(metaclass=DynamicModelMeta):
